(()=>{const old=document.querySelector('.t-banner');if(!old)return;const p=location.pathname.replace(/^\/+|\/+$/g,'')||'home';const map={pricing:['Choose your Tivione plan.','Simple durations. Full premium features.'],reseller:['Build your Tivione reseller business.','Flexible credits, professional tools and support that stays close.'],apps:['Choose your compatible player.','Clear app choices for every screen.'],guides:['Set up every screen with confidence.','Straightforward Tivione device guidance.'],tutorials:['Learn the essential setup steps.','Short tutorials for a smoother start.'],panel:['Control made simple.','A clear workflow for credits, accounts and support.'],blog:['Practical IPTV guidance.','Useful reading for players, devices and setup.'],contact:['Talk to a Tivione specialist.','Get help with plans, apps and reseller enquiries.']};const [title,desc]=map[p]||['Tivione information.','Clear answers and practical support.'];old.outerHTML='<section class="enterprise-banner"><div class="site-wrap"><div class="enterprise-shell"><div class="enterprise-live"><span><i class="enterprise-dot"></i>Tivione network: <b>all systems operational</b></span><span>Stable servers · Global EPG · 24/7 support</span></div><div class="enterprise-grid"><div class="enterprise-copy"><span class="enterprise-badge">Tivione IPTV platform</span><h1>'+title.replace('Tivione','<strong>Tivione</strong>')+'</h1><p>'+desc+'</p><div class="enterprise-features"><div class="enterprise-feature"><i>◈</i><div><b>Instant activation</b><span>A clear route from order to setup.</span></div></div><div class="enterprise-feature"><i>▣</i><div><b>22,000+ channels</b><span>Live viewing across compatible players.</span></div></div><div class="enterprise-feature"><i>◎</i><div><b>88,000+ VOD</b><span>Movies and series on demand.</span></div></div><div class="enterprise-feature"><i>↗</i><div><b>Dedicated support</b><span>Help when you need it.</span></div></div></div><div class="actions"><a class="btn" href="/pricing/">Explore plans</a><a class="btn ghost" href="/contact/">Talk to support</a></div></div><aside class="enterprise-card"><h2>'+ (p==='reseller'?'Tivione reseller options':'Tivione plan overview') +'</h2><p>'+ (p==='reseller'?'Select a credit package and ask the team about your setup.':'Five clear durations, one dependable service.') +'</p><div class="enterprise-mini"><div>Starter<b>'+ (p==='reseller'?'10 credits':'1 month') +'</b></div><div>Best value<b>'+ (p==='reseller'?'20+ credits':'24 months') +'</b></div><div>Feature<b>'+ (p==='reseller'?'API access':'Global EPG') +'</b></div><div>Support<b>24/7</b></div></div><div class="enterprise-summary"><div><span>'+ (p==='reseller'?'Starter price':'Subscription from') +'</span><b class="green">'+ (p==='reseller'?'€190':'€19') +'</b></div><div><span>Activation</span><b class="green">Instant</b></div><div><span>Status</span><b>Ready to activate</b></div></div><a class="btn" href="'+(p==='reseller'?'/reseller/':'/contact/')+'">Contact Tivione ↗</a></aside></div></div></div></section>';})();
